Template:
body {
font-family: 'Raleway', sans-serif!important;
}

.google-visualization-table-table {
font-family: 'Raleway', sans-serif!important;
}

.test1[data-balance="1"]
{display:none;}
.test1
{display:block; float:right;}
.test2[data-balance="1"]
{display:block;float:right;}
.test2
{display:none;}

.test3[data-balance="0"]
{display:none;}


.photo {
width:50px;
height: 50px;
float:left;
margin:5px 10px 5px 5px!important;
}

.photo-container {
 border-radius: 300px;
overflow: hidden;
width: 96px;
height: 96px;
margin: 0 auto;
border: solid 4px white;
margin:0 auto!important;
}

.name {
color:#4E423B;
margin-top:20px!important;
}

.about-container {
 background-color: #f1f1f1;
width:100%;
padding: 30px 10px;
text-align: center;
}

.about-name {
margin-bottom: 0px!important;
font-weight: initial;
color: #4E423B;
}
.about-nam {
margin-bottom: 0px!important;
font-weight: initial;
color: #009CE0;
}
.department {
margin-top: 0px!important;
color: #009CE0;
font-weight:bold;
}

.info-container {
text-align: left;
border-top: 1px solid #f8f8f8;
}

.basic-info-container{
padding: 4%;
vertical-align: top;
}

#sidebar {
display:flex;
}

a.reward-link {
  float: left;
  color: #1E90FF;
  font-weight: bold;
  text-decoration: none;
}
a.reward-link:hover {
  color: #FF4500; /* changes color on hover */
  text-decoration: underline;
}

/*** CSS for Awesome Table Gadget***/
/* loader progress bar */
.loader {
        background-color:#437af8;
}

/*** Configuration of FILTERS ***/

/** Labels of filters **/
.google-visualization-controls-label {
        color:#333;
        font-weight: 500!important;
}

/** StringFilter **/
.google-visualization-controls-stringfilter INPUT {
        border:1px solid #d9d9d9!important;
        color:#222;
}
.google-visualization-controls-stringfilter INPUT:hover {
        border:1px solid #b9b9b9;
        border-top:1px solid #a0a0a0;
}
.google-visualization-controls-stringfilter INPUT:focus {
        border:1px solid #4d90fe;
}

/* CategoryFilter & csvFilter hovered item in the dropdown */
.charts-menuitem-highlight {
        background-color:#009CE0!important;
        border-color:#009CE0!important;
        color:#FFF!important;
}


.google-visualization-table-tr-sel td, .google-visualization-table-tr-over td {
        background-color:#F1F1F1!important;
}

.google-visualization-table-table .gradient, .google-visualization-table-div-page .gradient {
        background: #009CE0 !important;
        color: #FFFFFF!important;
        font-size:1.3em!important;
}

a.reward-link {
  float: left;
  color: #1E90FF;
  font-weight: bold;
  text-decoration: none;
}
a.reward-link:hover {
  color: #FF4500; /* changes color on hover */
  text-decoration: underline;
}
